  1	package com.loja.service;
  2	
  3	import com.loja.model.*;
  4	import com.loja.repository.*;
  5	import com.loja.strategy.*;
  6	import com.loja.util.Money;
  7	import java.time.Instant;
  8	import java.util.*;
  9	
 10	public class OrderService {
 11	    private final ProductRepository productRepo;
 12	    private final OrderRepository orderRepo;
 13	    private final CustomerRepository customerRepo;
 14	    private final NotificationRepository notificationRepo;
 15	    private final CheckoutService checkoutService;
 16	    private final Map<String, String> paymentTracking = new HashMap<>();
 17	
 18	    public OrderService(ProductRepository productRepo, OrderRepository orderRepo,
 19	                       CustomerRepository customerRepo, NotificationRepository notificationRepo) {
 20	        this.productRepo = productRepo;
 21	        this.orderRepo = orderRepo;
 22	        this.customerRepo = customerRepo;
 23	        this.notificationRepo = notificationRepo;
 24	        this.checkoutService = new CheckoutService(productRepo, this);
 25	    }
 26	
 27	    public Order createOrder(CheckoutRequest request) throws CheckoutException {
 28	        OrderSummary summary = checkoutService.calculateSummary(request);
 29	
 30	        String orderId = generateOrderId();
 31	        Order order = new Order(
 32	            orderId,
 33	            request.customer.cpf,
 34	            request.customer.email,
 35	            OrderStatus.AWAITING_PAYMENT,
 36	            Instant.now(),
 37	            summary,
 38	            new ArrayList<>(request.items)
 39	        );
 40	
 41	        orderRepo.create(order);
 42	
 43	        Customer customer = customerRepo.findByCpf(request.customer.cpf);
 44	        if (customer == null) {
 45	            customerRepo.createOrUpdate(request.customer.cpf, 0.0);
 46	        }
 47	
 48	        return order;
 49	    }
 50	
 51	    public Order processPayment(String orderId, String transactionId, String paidAtStr) throws OrderException {
 52	        Order order = orderRepo.findById(orderId);
 53	        if (order == null) {
 54	            throw new OrderException("ORDER_NOT_FOUND", 404);
 55	        }
 56	
 57	        if (transactionId == null || paidAtStr == null) {
 58	            throw new OrderException("INVALID_ORDER", 422);
 59	        }
 60	
 61	        if (order.status != OrderStatus.AWAITING_PAYMENT) {
 62	            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
 63	        }
 64	
 65	        synchronized (paymentTracking) {
 66	            String key = orderId + ":" + transactionId;
 67	            if (paymentTracking.containsKey(key)) {
 68	                return order;
 69	            }
 70	            paymentTracking.put(key, "processed");
 71	        }
 72	
 73	        Instant paidAt = Instant.parse(paidAtStr);
 74	        Instant expiryTime = order.createdAt.plusSeconds(48 * 3600);
 75	
 76	        if (paidAt.isAfter(expiryTime)) {
 77	            orderRepo.updateStatus(orderId, OrderStatus.CANCELLED);
 78	            Notification notification = new Notification(
 79	                generateNotificationId(),
 80	                NotificationType.ORDER_CANCELLED,
 81	                orderId,
 82	                order.cpf,
 83	                NotificationStatus.NEW
 84	            );
 85	            notificationRepo.create(notification);
 86	            throw new OrderException("ORDER_EXPIRED", 409);
 87	        }
 88	
 89	        validateStockAvailability(order);
 90	
 91	        orderRepo.updateStatusAndPaidAt(orderId, OrderStatus.PAID, paidAt);
 92	
 93	        deductStock(order);
 94	
 95	        addCustomerCredit(order);
 96	
 97	        Notification notification = new Notification(
 98	            generateNotificationId(),
 99	            NotificationType.PAYMENT_APPROVED,
100	            orderId,
101	            order.cpf,
102	            NotificationStatus.NEW
103	        );
104	        notificationRepo.create(notification);
105	
106	        order.status = OrderStatus.PAID;
107	        order.paidAt = paidAt;
108	        return order;
109	    }
110	
111	    public Order shipOrder(String orderId, String trackingCode) throws OrderException {
112	        Order order = orderRepo.findById(orderId);
113	        if (order == null) {
114	            throw new OrderException("ORDER_NOT_FOUND", 404);
115	        }
116	
117	        if (trackingCode == null) {
118	            throw new OrderException("INVALID_ORDER", 422);
119	        }
120	
121	        if (order.status != OrderStatus.PAID) {
122	            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
123	        }
124	
125	        orderRepo.updateTrackingCode(orderId, trackingCode);
126	        orderRepo.updateStatus(orderId, OrderStatus.SHIPPED);
127	
128	        order.trackingCode = trackingCode;
129	        order.status = OrderStatus.SHIPPED;
130	
131	        Notification notification = new Notification(
132	            generateNotificationId(),
133	            NotificationType.ORDER_SHIPPED,
134	            orderId,
135	            order.cpf,
136	            NotificationStatus.NEW
137	        );
138	        notificationRepo.create(notification);
139	
140	        return order;
141	    }
142	
143	    public Order deliverOrder(String orderId) throws OrderException {
144	        Order order = orderRepo.findById(orderId);
145	        if (order == null) {
146	            throw new OrderException("ORDER_NOT_FOUND", 404);
147	        }
148	
149	        if (order.status != OrderStatus.SHIPPED) {
150	            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
151	        }
152	
153	        orderRepo.updateStatus(orderId, OrderStatus.DELIVERED);
154	        order.status = OrderStatus.DELIVERED;
155	
156	        return order;
157	    }
158	
159	    public Order cancelOrder(String orderId) throws OrderException {
160	        Order order = orderRepo.findById(orderId);
161	        if (order == null) {
162	            throw new OrderException("ORDER_NOT_FOUND", 404);
163	        }
164	
165	        if (order.status == OrderStatus.DELIVERED || order.status == OrderStatus.CANCELLED) {
166	            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
167	        }
168	
169	        if (order.status == OrderStatus.SHIPPED) {
170	            throw new OrderException("OPERATION_NOT_ALLOWED", 409);
171	        }
172	
173	        boolean wasPaid = order.status == OrderStatus.PAID;
174	
175	        orderRepo.updateStatus(orderId, OrderStatus.CANCELLED);
176	
177	        if (wasPaid) {
178	            restoreStock(order);
179	            subtractCustomerCredit(order);
180	        }
181	
182	        Notification notification = new Notification(
183	            generateNotificationId(),
184	            NotificationType.ORDER_CANCELLED,
185	            orderId,
186	            order.cpf,
187	            NotificationStatus.NEW
188	        );
189	        notificationRepo.create(notification);
190	
191	        order.status = OrderStatus.CANCELLED;
192	        return order;
193	    }
194	
195	    private void validateStockAvailability(Order order) throws OrderException {
196	        for (OrderItem item : order.items) {
197	            Product product = productRepo.findBySku(item.sku);
198	            if (product == null || product.stock < item.quantity) {
199	                orderRepo.updateStatus(order.id, OrderStatus.CANCELLED);
200	                Notification notification = new Notification(
201	                    generateNotificationId(),
202	                    NotificationType.ORDER_CANCELLED,
203	                    order.id,
204	                    order.cpf,
205	                    NotificationStatus.NEW
206	                );
207	                notificationRepo.create(notification);
208	                throw new OrderException("INSUFFICIENT_STOCK", 409);
209	            }
210	        }
211	    }
212	
213	    private void deductStock(Order order) {
214	        for (OrderItem item : order.items) {
215	            productRepo.updateStock(item.sku, item.quantity);
216	        }
217	    }
218	
219	    private void restoreStock(Order order) {
220	        for (OrderItem item : order.items) {
221	            productRepo.restoreStock(item.sku, item.quantity);
222	        }
223	    }
224	
225	    private void addCustomerCredit(Order order) {
226	        customerRepo.addCredit(order.cpf, order.summary.nextPurchaseCredit);
227	    }
228	
229	    private void subtractCustomerCredit(Order order) {
230	        customerRepo.subtractCredit(order.cpf, order.summary.nextPurchaseCredit);
231	    }
232	
233	    private String generateOrderId() {
234	        return UUID.randomUUID().toString();
235	    }
236	
237	    private String generateNotificationId() {
238	        return UUID.randomUUID().toString();
239	    }
240	
241	    public Order findOrder(String orderId) {
242	        return orderRepo.findById(orderId);
243	    }
244	
245	    public OrderRepository getOrderRepo() {
246	        return orderRepo;
247	    }
248	}

